/**
 * Valorant — panneau second écran
 * Lit l'API locale du client Riot (lecture seule) et sert une page sur localhost.
 * Aucune injection dans le jeu, aucun envoi de données ailleurs que vers Riot.
 */
const https = require("node:https");
const fs = require("node:fs");
const path = require("node:path");
const os = require("node:os");
const http = require("node:http");


const ICI = path.dirname(process.execPath);
const child_process = require("node:child_process");

/* Sans console (mode fenetre), tout ce qui etait affiche part dans un journal. */
const JOURNAL = path.join(ICI, "valo-journal.log");
const note = globalThis.__note || function(){
  const t = new Date().toISOString().slice(11, 19);
  const m = Array.prototype.map.call(arguments, x => typeof x === "string" ? x : require("node:util").inspect(x)).join(" ");
  try{ fs.appendFileSync(JOURNAL, t + "  " + m + "\n"); }catch(e){}
};
console.log = note; console.error = note; console.warn = note; console.info = note;
process.on("uncaughtException", e => { note("PLANTAGE", e && e.stack || String(e)); });
process.on("unhandledRejection", e => { note("REJET", e && e.stack || String(e)); });
note("demarrage, exe =", process.execPath);

/* Ouvre une vraie fenetre applicative (Edge ou Chrome en mode --app :
   pas d'onglets, pas de barre d'adresse). Fermer la fenetre arrete l'appli. */
function ouvrirFenetre(url){
  const pf = process.env.ProgramFiles || "";
  const px = process.env["ProgramFiles(x86)"] || "";
  const la = process.env.LOCALAPPDATA || "";
  const candidats = [
    px + "\\Microsoft\\Edge\\Application\\msedge.exe",
    pf + "\\Microsoft\\Edge\\Application\\msedge.exe",
    pf + "\\Google\\Chrome\\Application\\chrome.exe",
    px + "\\Google\\Chrome\\Application\\chrome.exe",
    la + "\\Google\\Chrome\\Application\\chrome.exe"
  ];
  let nav = null;
  for(const c of candidats){ try{ if(c && fs.existsSync(c)){ nav = c; break; } }catch(e){} }
  if(!nav){
    note("aucun navigateur applicatif trouve, ouverture classique");
    try{ const q = child_process.spawn("cmd", ["/c", "start", "", url], { detached:true, stdio:"ignore" }); q.on("error", e => note("start:", e.message)); q.unref(); }catch(e){ note(e.message); }
    return;
  }
  const profil = path.join(os.tmpdir(), "valo-tracker-fenetre");
  const args = [
    "--app=" + url,
    "--user-data-dir=" + profil,
    "--window-size=1360,900",
    "--no-first-run", "--no-default-browser-check", "--disable-features=Translate",
    "--app-auto-launched"
  ];
  note("fenetre via", nav);
  try{
    const p = child_process.spawn(nav, args, { stdio:"ignore", detached:true });
    p.on("error", e => note("echec ouverture fenetre :", e.message));
    p.unref();
  }catch(e){ note("echec spawn :", e.message); }
}
const PORT_WEB = 7777;
const REGION = (process.env.VALO_REGION || "eu").toLowerCase();
const PD = `https://pd.${REGION}.a.pvp.net`;
const GLZ = `https://glz-${REGION}-1.${REGION}.a.pvp.net`;
const PLATFORM = Buffer.from(JSON.stringify({
  platformType: "PC", platformOS: "Windows",
  platformOSVersion: "10.0.19042.1.256.64bit", platformChipset: "Unknown"
})).toString("base64");

/* ---------- client local (certificat auto-signé : on ne vérifie pas) ---------- */
function localGet(port, pass, chemin){
  return new Promise((ok, ko) => {
    const req = https.request({
      host: "127.0.0.1", port, path: chemin, method: "GET", rejectUnauthorized: false,
      headers: { Authorization: "Basic " + Buffer.from("riot:" + pass).toString("base64") }
    }, res => {
      let d = ""; res.on("data", c => d += c);
      res.on("end", () => { try { ok(JSON.parse(d)); } catch(e){ ko(new Error("réponse illisible")); } });
    });
    req.on("error", ko); req.setTimeout(5000, () => req.destroy(new Error("délai dépassé"))); req.end();
  });
}

function lireLockfile(){
  const p = path.join(process.env.LOCALAPPDATA || "", "Riot Games", "Riot Client", "Config", "lockfile");
  if(!fs.existsSync(p)) return null;
  const [, , port, pass] = fs.readFileSync(p, "utf8").split(":");
  return { port, pass };
}

/* ---------- métadonnées du jeu, chargées une fois ---------- */
let META = { agents:{}, maps:{}, tiers:{}, pret:false };
async function chargerMeta(){
  try{
    const [a, m, t] = await Promise.all([
      fetch("https://valorant-api.com/v1/agents?isPlayableCharacter=true&language=fr-FR").then(r=>r.json()),
      fetch("https://valorant-api.com/v1/maps?language=fr-FR").then(r=>r.json()),
      fetch("https://valorant-api.com/v1/competitivetiers?language=fr-FR").then(r=>r.json()),
    ]);
    for(const x of a.data) META.agents[x.uuid.toLowerCase()] = { nom:x.displayName, img:x.displayIconSmall };
    for(const x of m.data) META.maps[x.mapUrl] = { nom:x.displayName, img:x.listViewIcon };
    const set = t.data[t.data.length-1];
    for(const x of set.tiers) META.tiers[x.tier] = { nom:x.divisionName === "NON CLASSÉ" ? "Non classé" : x.tierName, img:x.smallIcon, couleur:"#"+(x.color||"ffffffff").slice(0,6) };
    META.pret = true;
  }catch(e){ console.log("métadonnées indisponibles (le panneau marchera sans icônes)"); }
}

/* ---------- session Riot ---------- */
let SESSION = null;
async function ouvrirSession(){
  const lf = lireLockfile();
  if(!lf) throw new Error("Client Riot non lancé (lockfile absent)");
  const tok = await localGet(lf.port, lf.pass, "/entitlements/v1/token");
  if(!tok || !tok.accessToken) throw new Error("jetons illisibles");
  let version = SESSION?.version;
  if(!version){
    try { version = (await fetch("https://valorant-api.com/v1/version").then(r=>r.json())).data.riotClientVersion; }
    catch(e){ throw new Error("version du client introuvable"); }
  }
  SESSION = { puuid: tok.subject, lf, entetes: {
    Authorization: "Bearer " + tok.accessToken,
    "X-Riot-Entitlements-JWT": tok.token,
    "X-Riot-ClientVersion": version,
    "X-Riot-ClientPlatform": PLATFORM
  }, version };
  return SESSION;
}

const appel = async (url, init) => {
  const r = await fetch(url, Object.assign({ headers: SESSION.entetes }, init||{}));
  if(!r.ok){ const e = new Error("HTTP " + r.status); e.status = r.status; throw e; }
  return r.json();
};

/* ---------- statistiques réelles des joueurs ----------
   On passe par le proxy du tracker web : la clé HenrikDev reste sur Netlify,
   elle n'est jamais dans ce programme. Une entrée est gardée 10 minutes. */
const PROXY = process.env.VALO_PROXY || "https://tracker-valo-mk.netlify.app/api";
const cacheStats = new Map();
let DIAG = [];   // pourquoi telle statistique manque — écrit dans le fichier de debug

async function statsJoueur(nomComplet){
  if(!nomComplet) return null;
  const cache = cacheStats.get(nomComplet);
  if(cache && Date.now() - cache.t < 600000) return cache.v;
  const [nom, tag] = nomComplet.split("#");
  if(!nom || !tag){ DIAG.push(`${nomComplet} : pseudo illisible`); return null; }
  const u = s => `${PROXY}${s}`;
  let v = null;
  try{
    const url = u(`/v1/stored-matches/${REGION}/${encodeURIComponent(nom)}/${encodeURIComponent(tag)}?mode=competitive&size=5`);
    const r = await fetch(url);
    if(!r.ok){ DIAG.push(`${nomComplet} : HTTP ${r.status} sur stored-matches`); }
    if(r.ok){
      const j = await r.json();
      const ms = (j.data || []).filter(m => m && m.stats);
      if(!ms.length) DIAG.push(`${nomComplet} : 0 partie classée renvoyée`);
      if(ms.length){
        let k=0, d=0, sc=0, rounds=0, w=0, head=0, body=0, leg=0;
        const forme = [], agents = {}, parMap = {};
        for(const m of ms){
          const st = m.stats, t = m.teams || {};
          const cote = (st.team||"").toLowerCase();
          const mine = t[cote], other = t[cote === "red" ? "blue" : "red"];
          k+=st.kills||0; d+=st.deaths||0; sc+=st.score||0;
          const nR = (mine!=null && other!=null) ? mine+other : 0;
          rounds += nR;
          const gagne = (mine!=null && other!=null) ? mine > other : null;
          if(gagne) w++;
          forme.push(gagne);
          const ag = m.stats.character?.name; if(ag) agents[ag] = (agents[ag]||0)+1;
          const mp = m.meta?.map?.name;
          if(mp){ const e = parMap[mp] || (parMap[mp] = { n:0, w:0 }); e.n++; if(gagne) e.w++; }
          const sh = st.shots||{}; head+=sh.head||0; body+=sh.body||0; leg+=sh.leg||0;
        }
        const tirs = head+body+leg;
        const topAgents = Object.entries(agents).sort((a,b)=>b[1]-a[1]).slice(0,2).map(([nom,c])=>({nom,n:c}));
        v = { n: ms.length, kd: d ? k/d : k, acs: rounds ? sc/rounds : null,
              hs: tirs ? head/tirs : null, wr: ms.length ? w/ms.length : null,
              forme: forme.slice(0,5), agents: topAgents, parMap };
      }
    }
  }catch(e){ DIAG.push(`${nomComplet} : ${e.message}`); }
  cacheStats.set(nomComplet, { t: Date.now(), v });
  return v;
}

/* Pour soi uniquement : un historique plus large, pour savoir quel agent
   rapporte sur la map qu'on est en train de jouer. */
let MOI_HISTO = { t:0, v:null };
async function monHistorique(nomComplet){
  if(!nomComplet) return null;
  if(Date.now() - MOI_HISTO.t < 900000) return MOI_HISTO.v;
  const [nom, tag] = nomComplet.split("#");
  let v = null;
  try{
    const r = await fetch(`${PROXY}/v1/stored-matches/${REGION}/${encodeURIComponent(nom)}/${encodeURIComponent(tag)}?mode=competitive&size=20`);
    if(r.ok){
      const j = await r.json();
      const parMapAgent = {};
      for(const m of (j.data || [])){
        const st = m.stats, t = m.teams || {};
        if(!st) continue;
        const cote = (st.team||"").toLowerCase();
        const mine = t[cote], other = t[cote === "red" ? "blue" : "red"];
        const gagne = (mine!=null && other!=null) ? mine > other : null;
        const mp = m.meta?.map?.name, ag = st.character?.name;
        if(!mp || !ag) continue;
        const cle = mp + "|" + ag;
        const e = parMapAgent[cle] || (parMapAgent[cle] = { map:mp, agent:ag, n:0, w:0 });
        e.n++; if(gagne) e.w++;
      }
      v = Object.values(parMapAgent);
    }
  }catch(e){ DIAG.push("historique perso : " + e.message); }
  MOI_HISTO = { t: Date.now(), v };
  return v;
}

/* ---------- noms et rangs, mis en cache pour la session ---------- */
const cacheNoms = new Map(), cacheRangs = new Map();

async function noms(puuids){
  // Un joueur en incognito a explicitement demandé à ne pas être identifié :
  // on ne demande pas son nom, et on ne l'affiche pas.
  const manquants = puuids.filter(p => !cacheNoms.has(p));
  if(manquants.length){
    try{
      const res = await appel(`${PD}/name-service/v2/players`, {
        method: "PUT",
        headers: Object.assign({ "Content-Type": "application/json" }, SESSION.entetes),
        body: JSON.stringify(manquants)
      });
      for(const n of res) cacheNoms.set(n.Subject, `${n.GameName}#${n.TagLine}`);
    }catch(e){ /* on affichera « joueur masqué » */ }
  }
  return puuids.map(p => cacheNoms.get(p) || null);
}

async function rang(puuid){
  if(cacheRangs.has(puuid)) return cacheRangs.get(puuid);
  let r = { tier:null, peak:null };
  try{
    const m = await appel(`${PD}/mmr/v1/players/${puuid}`);
    r.tier = m?.LatestCompetitiveUpdate?.TierAfterUpdate ?? null;
    const saisons = m?.QueueSkills?.competitive?.SeasonalInfoBySeasonID || {};
    let peak = 0;
    for(const s of Object.values(saisons)){
      if(s?.CompetitiveTier > peak) peak = s.CompetitiveTier;
      if(s?.Rank > peak) peak = s.Rank;
    }
    r.peak = peak || null;
    if(r.tier == null && peak) r.tier = null;
  }catch(e){ /* profil non lisible */ }
  cacheRangs.set(puuid, r);
  return r;
}

/* ---------- indice de smurf, avant que la partie commence ----------
   Sans statistiques de partie, le seul signal disponible est l'écart entre
   l'ancienneté du compte et le rang atteint. On reste prudent : on signale,
   on n'accuse pas. */
function indice(j, tiersLobby, acsLobby){
  const lv = j.niveau, t = j.tier, st = j.stats;
  // Riot renvoie AccountLevel = 0 quand le joueur masque son niveau. Le traiter
  // comme « niveau très bas » signalerait tous les comptes discrets comme smurfs :
  // sans niveau connu, on ne conclut pas.
  if(lv == null || lv <= 0) return null;
  const med = tiersLobby.length ? tiersLobby.slice().sort((a,b)=>a-b)[Math.floor(tiersLobby.length/2)] : null;
  const raisons = [];
  let score = 0;
  if(lv < 20){ score += 45; raisons.push(`niveau ${lv}`); }
  else if(lv < 40){ score += 30; raisons.push(`niveau ${lv}`); }
  else if(lv < 70){ score += 15; raisons.push(`niveau ${lv}`); }
  if(t && med && t >= med + 3){ score += 30; raisons.push("rang au-dessus du lobby"); }
  if(t && lv && lv < 40 && t >= 15){ score += 25; raisons.push("rang élevé pour un compte neuf"); }
  // Avec les statistiques réelles, on retrouve la précision du tracker web :
  // un compte récent qui écrase son lobby, plutôt qu'un simple niveau bas.
  if(st){
    if(acsLobby && st.acs && st.acs >= acsLobby * 1.45){ score += 25; raisons.push(`${Math.round(st.acs)} d'ACS`); }
    if(st.kd >= 1.8){ score += 20; raisons.push(`${st.kd.toFixed(1)} de K/D`); }
    else if(st.kd >= 1.4){ score += 10; raisons.push(`${st.kd.toFixed(1)} de K/D`); }
    if(st.hs != null && st.hs >= 0.28){ score += 15; raisons.push(`${Math.round(st.hs*100)} % de tête`); }
    if(st.wr != null && st.wr >= 0.8 && st.n >= 4){ score += 10; raisons.push("série de victoires"); }
  }
  if(score < 45 || !raisons.length) return null;
  return { score: Math.min(100, score), sur: score >= 70, raisons };
}

const MODES_FR = { Bomb:"Standard", Deathmatch:"Match à mort", HURM:"Match à mort par équipe",
  QuickBomb:"Spike Rush", GunRange:"Stand de tir", OneForAll:"Réplication", Swiftplay:"Partie rapide" };
function modeFr(id){
  const cle = (id || "").split("/GameModes/")[1]?.split("/")[0];
  return MODES_FR[cle] || cle || null;
}

/* ---------- score en direct ----------
   Le client tient à jour sa « présence » (ce que voient tes amis). Elle contient
   l'état de session et le score de la partie. C'est la seule donnée live que
   Riot expose à un programme externe : pas de kills, pas de positions. */
const ETATS_FR = { MENUS:"menu", PREGAME:"agent select", INGAME:"en partie" };
let DERNIERE_PRESENCE_BRUTE = null;
async function presence(){
  try{
    const r = await localGet(SESSION.lf.port, SESSION.lf.pass, "/chat/v4/presences");
    const p = (r.presences || []).find(x => x.puuid === SESSION.puuid);
    if(!p || !p.private) return null;
    const d = JSON.parse(Buffer.from(p.private, "base64").toString("utf8"));
    DERNIERE_PRESENCE_BRUTE = d;
    return {
      etat: ETATS_FR[d.sessionLoopState] || d.sessionLoopState || null,
      nous: d.partyOwnerMatchScoreAllyTeam ?? null,
      eux: d.partyOwnerMatchScoreEnemyTeam ?? null,
      file: d.queueId || null,
      groupe: d.partySize || null
    };
  }catch(e){ return null; }
}

/* ---------- chronologie des rounds, reconstruite en direct ----------
   Riot ne diffuse pas les événements d'un round. Mais le score, lui, bouge à
   chaque round : en suivant ses variations on sait lequel a été gagné ou perdu,
   et quand. C'est le maximum de granularité disponible depuis l'extérieur. */
let SUIVI = { matchId:null, nous:0, eux:0, rounds:[] };
function suivreScore(matchId, nous, eux){
  if(nous == null || eux == null) return SUIVI.rounds;
  if(SUIVI.matchId !== matchId){ SUIVI = { matchId, nous:0, eux:0, rounds:[] }; }
  // rattrapage si on démarre l'app en cours de partie
  if(!SUIVI.rounds.length && (nous + eux) > 0){
    for(let i=0;i<nous;i++) SUIVI.rounds.push({ n:SUIVI.rounds.length+1, gagne:true, rattrape:true });
    for(let i=0;i<eux;i++)  SUIVI.rounds.push({ n:SUIVI.rounds.length+1, gagne:false, rattrape:true });
    SUIVI.nous = nous; SUIVI.eux = eux;
    return SUIVI.rounds;
  }
  while(nous > SUIVI.nous){ SUIVI.nous++; SUIVI.rounds.push({ n:SUIVI.rounds.length+1, gagne:true,  t:Date.now() }); }
  while(eux  > SUIVI.eux ){ SUIVI.eux++;  SUIVI.rounds.push({ n:SUIVI.rounds.length+1, gagne:false, t:Date.now() }); }
  return SUIVI.rounds;
}

/* ---------- état courant ---------- */
let ETAT = { phase:"demarrage", message:"Connexion au client Riot…", joueurs:[], maj:null };
let ETAT_DIAG = null;

async function rafraichir(){
  DIAG = [];
  try{
    if(!SESSION) await ouvrirSession();
    const me = SESSION.puuid;
    let brut = null, phase = null;

    try{
      const cg = await appel(`${GLZ}/core-game/v1/players/${me}`);
      brut = await appel(`${GLZ}/core-game/v1/matches/${cg.MatchID}`);
      phase = "partie";
    }catch(e){
      if(e.status !== 404 && e.status !== 400) throw e;
      try{
        const pg = await appel(`${GLZ}/pregame/v1/players/${me}`);
        brut = await appel(`${GLZ}/pregame/v1/matches/${pg.MatchID}`);
        phase = "agentselect";
      }catch(e2){
        if(e2.status !== 404 && e2.status !== 400) throw e2;
        const pm = await presence();
        ETAT = { phase:"menu", joueurs:[], maj:Date.now(),
                 message: pm?.groupe > 1 ? `Aucune partie en cours — groupe de ${pm.groupe}.`
                                         : "Aucune partie en cours. Lance une file." };
        return;
      }
    }

    const pres = await presence();
    ETAT_DIAG = { proxy: PROXY, region: REGION, notes: DIAG.slice(-40) };
    try{ fs.writeFileSync(path.join(ICI, "debug-dernier-match.json"),
        JSON.stringify({ presence: pres, presenceBrute: DERNIERE_PRESENCE_BRUTE, match: brut }, null, 2)); }catch(e){}

    const liste = phase === "partie"
      ? (brut.Players || [])
      : ([...(brut.AllyTeam?.Players || []), ...(brut.EnemyTeam?.Players || [])]);

    const monEquipe = phase === "partie"
      ? (liste.find(p => p.Subject === me)?.TeamID)
      : (brut.AllyTeam?.TeamID ?? "Blue");

    // Certains modes (match à mort) n'ont pas d'équipes : tout le monde partage
    // le même TeamID. On affiche alors une liste unique plutôt qu'un faux « nous / eux ».
    // En agent select, TeamID est vide pour tout le monde — ce n'est pas le même cas :
    // on ne voit que sa propre équipe, et c'est bien une équipe.
    const sansEquipes = phase === "partie"
      && new Set(liste.map(p => p.TeamID)).size <= 1 && liste.length > 2;

    const joueurs = liste.map(p => {
      const pi = p.PlayerIdentity || {};
      // AccountLevel vaut 0 quand le joueur masque son niveau : c'est « inconnu ».
      const niveauMasque = !!pi.HideAccountLevel || !pi.AccountLevel;
      return {
        puuid: p.Subject,
        moi: p.Subject === me,
        equipe: p.TeamID ?? monEquipe,
        allie: sansEquipes ? true : ((p.TeamID ?? monEquipe) === monEquipe),
        agentId: (p.CharacterID || "").toLowerCase(),
        niveau: niveauMasque ? null : pi.AccountLevel,
        niveauMasque,
        incognito: !!pi.Incognito,
        tier: p.CompetitiveTier || p.SeasonalBadgeInfo?.Rank || null,
        nom: null, peak: null
      };
    });

    // L'incognito sert à se masquer aux autres, pas à soi-même : on s'affiche
    // toujours, sinon le panneau cache ses propres statistiques à son utilisateur.
    const visibles = joueurs.filter(j => j.moi || !j.incognito).map(j => j.puuid);
    const n = await noms(visibles);
    visibles.forEach((id, i) => {
      const j = joueurs.find(x => x.puuid === id);
      if(j) j.nom = n[i];
    });

    for(const j of joueurs){
      if(j.tier == null || !j.peak){
        const r = await rang(j.puuid);
        if(j.tier == null) j.tier = r.tier;
        j.peak = r.peak;
      }
    }

    // stats réelles, trois joueurs à la fois pour rester doux avec le quota
    const aStats = joueurs.filter(j => j.nom);
    for(let i = 0; i < aStats.length; i += 3){
      const lot = aStats.slice(i, i + 3);
      const res = await Promise.all(lot.map(j => statsJoueur(j.nom)));
      lot.forEach((j, k) => { j.stats = res[k]; });
    }

    const tiers = joueurs.map(j => j.tier).filter(t => t > 0);
    const acs = joueurs.map(j => j.stats?.acs).filter(v => v > 0);
    const acsLobby = acs.length ? acs.reduce((a,b)=>a+b,0)/acs.length : null;
    for(const j of joueurs) j.smurf = j.moi ? null : indice(j, tiers, acsLobby);

    // Le joueur le plus dangereux d'en face : ce que les bons trackers mettent
    // en avant, parce que c'est la seule information qui change ta façon de jouer.
    const enFace = joueurs.filter(j => !j.allie && j.stats);
    if(enFace.length){
      const note = j => (j.stats.acs||0)/10 + (j.stats.kd||0)*20 + (j.tier||0)*1.5;
      const pire = enFace.reduce((a,b) => note(b) > note(a) ? b : a);
      pire.menace = true;
    }

    // Moyennes par camp, pour situer le rapport de force d'un coup d'œil.
    const moy = (arr, f) => { const v = arr.map(f).filter(x => x > 0); return v.length ? v.reduce((a,b)=>a+b,0)/v.length : null; };
    const nous = joueurs.filter(j => j.allie), eux = joueurs.filter(j => !j.allie);
    const camps = (nous.length && eux.length) ? {
      nous: { acs: moy(nous, j=>j.stats?.acs), kd: moy(nous, j=>j.stats?.kd), rang: moy(nous, j=>j.tier) },
      eux:  { acs: moy(eux,  j=>j.stats?.acs), kd: moy(eux,  j=>j.stats?.kd), rang: moy(eux,  j=>j.tier) }
    } : null;

    // Quel agent te rapporte sur cette map — l'équivalent des suggestions d'agent.
    let conseil = null;
    const moiJ = joueurs.find(j => j.moi);
    const mapNom = META.maps[brut.MapID]?.nom;
    if(moiJ?.nom && mapNom){
      const h = await monHistorique(moiJ.nom);
      if(h){
        const surMap = h.filter(x => x.map === mapNom && x.n >= 2).sort((a,b) => (b.w/b.n) - (a.w/a.n));
        if(surMap.length) conseil = { map: mapNom, agent: surMap[0].agent, w: surMap[0].w, n: surMap[0].n };
      }
    }

    ETAT = {
      phase, maj: Date.now(),
      map: META.maps[brut.MapID]?.nom || brut.MapID || null,
      mapImg: META.maps[brut.MapID]?.img || null,
      mode: modeFr(brut.ModeID),
      sansEquipes,
      camps, conseil,
      score: pres && pres.nous != null ? { nous: pres.nous, eux: pres.eux } : null,
      rounds: pres ? suivreScore(brut.MatchID, pres.nous, pres.eux) : [],
      groupe: pres?.groupe ?? null,
      joueurs: joueurs.map(j => Object.assign(j, {
        agent: META.agents[j.agentId]?.nom || null,
        agentImg: META.agents[j.agentId]?.img || null,
        rangNom: META.tiers[j.tier]?.nom || null,
        rangImg: META.tiers[j.tier]?.img || null,
        rangCouleur: META.tiers[j.tier]?.couleur || null,
        peakNom: META.tiers[j.peak]?.nom || null
      })),
      message: null
    };
    try{ fs.writeFileSync(path.join(ICI, "debug-etat.json"),
      JSON.stringify({ diag: ETAT_DIAG, etat: ETAT }, null, 2)); }catch(e){}
  }catch(e){
    SESSION = null;
    ETAT = { phase:"erreur", message: e.message || String(e), joueurs:[], maj:Date.now() };
  }
}

/* ---------- serveur web ----------
   Deux applications sur le même serveur : le panneau live et le tracker complet.
   Les appels /api et /archive du tracker sont relayés vers le site Netlify, qui
   détient la clé et l'archive — on n'a donc aucune clé à stocker ici. */
const AMONT = (process.env.VALO_SITE || "https://tracker-valo-mk.netlify.app").replace(/\/+$/, "");
const fichier = (nom, type) => (res) => {
  const buf = PAGES[nom];
  if(!buf){ res.writeHead(404); return res.end("introuvable"); }
  res.writeHead(200, { "content-type": type, "cache-control":"no-store" });
  res.end(buf);
};

async function relayer(req, res){
  const cible = AMONT + req.url;
  try{
    const init = { method: req.method, headers: { "content-type":"application/json" } };
    if(req.method === "PUT" || req.method === "POST"){
      init.body = await new Promise(ok => { let d=""; req.on("data",c=>d+=c); req.on("end",()=>ok(d)); });
    }
    const r = await fetch(cible, init);
    const txt = await r.text();
    res.writeHead(r.status, { "content-type": r.headers.get("content-type") || "application/json", "cache-control":"no-store" });
    res.end(txt);
  }catch(e){
    res.writeHead(502, { "content-type":"application/json" });
    res.end(JSON.stringify({ errors:[{ message:"Site amont injoignable : " + e.message }] }));
  }
}

const SERVEUR = http.createServer(async (req, res) => {
  const u = (req.url || "/").split("?")[0];
  if(u.startsWith("/state")){
    res.writeHead(200, { "content-type":"application/json; charset=utf-8", "cache-control":"no-store" });
    return res.end(JSON.stringify(ETAT));
  }
  if(u === "/vivant"){
    VIVANT.vu = Date.now(); VIVANT.demarre = true;
    res.writeHead(200, { "content-type":"text/plain", "cache-control":"no-store" });
    return res.end("ok");
  }
  if(u === "/maj"){
    res.writeHead(200, { "content-type":"application/json; charset=utf-8", "cache-control":"no-store" });
    return res.end(JSON.stringify(MAJ));
  }
  if(u.startsWith("/api/") || u === "/archive") return relayer(req, res);
  if(u === "/tracker" || u === "/tracker.html") return fichier("tracker.html", "text/html; charset=utf-8")(res);
  if(u === "/sw.js" || u === "/manifest.webmanifest"){ res.writeHead(404); return res.end(""); }
  return fichier("index.html", "text/html; charset=utf-8")(res);
});
SERVEUR.on("error", (e) => {
  if(e && e.code === "EADDRINUSE"){
    note("deja lance sur le port " + PORT_WEB + " : j'ouvre simplement la fenetre");
    ouvrirFenetre("http://localhost:" + PORT_WEB);
    setTimeout(() => process.exit(0), 1500);
  } else { note("erreur serveur :", e && e.message); }
});
SERVEUR.listen(PORT_WEB, () => {
  note("serveur pret : http://localhost:" + PORT_WEB);
  if(VEILLE){ note("mode veille : la fenetre s'ouvrira au lancement de Valorant"); }
  else ouvrirFenetre("http://localhost:" + PORT_WEB);
});

/* Mode veille : demarre avec Windows, reste invisible, ouvre la fenetre
   des que Valorant est lance. */
const JEU_ACTIF = new Set(["menu", "agentselect", "partie"]);
setInterval(() => {
  if(!VEILLE) return;
  const actif = ETAT && JEU_ACTIF.has(ETAT.phase);
  if(!actif){ ARME = true; return; }
  if(ARME && !FENETRE_OUVERTE){
    note("Valorant detecte (" + ETAT.phase + ") : ouverture de la fenetre");
    FENETRE_OUVERTE = true;
    ouvrirFenetre("http://localhost:" + PORT_WEB);
  }
}, 3000);

(async () => { await chargerMeta(); await rafraichir(); })();
setInterval(rafraichir, 3000);
